interface Binding { kind: "var" | "type" | "namespace"; decl: Node }
class Scope {
  private readonly symbols = new Map<string, Binding>();
  constructor(readonly parent: Scope | null = null) {}
  define(name: string, sym: Binding): boolean {          // dup -> false
    if (this.symbols.has(name)) return false; this.symbols.set(name, sym); return true;
  }
  lookup(name: string): Binding | undefined {            // innermost outward
    for (let s: Scope | null = this; s; s = s.parent) {
      const sym = s.symbols.get(name); if (sym !== undefined) return sym;
    }
  }
}

